<script setup lang="ts">
import {computed,nextTick,onMounted,onBeforeUnmount,ref} from 'vue';
import AdminAudit from './components/AdminAudit.vue';
import {Headphones,ShieldCheck,MessageSquare,LogOut,ArrowUp,Search,Check,LockKeyhole,ClipboardList} from '@lucide/vue';
interface Ticket {id:string;user_id:string;username:string;phone_masked:string;title:string;status:string;operator?:string;created_at:string;updated_at:string}
interface Review {id:string;user_id:string;username:string;phone_masked:string;note:string;status:string;review_note?:string;created_at:string}
interface Chat {id:string;role:string;kind:string;text:string;created_at:string;data:Record<string,any>}
const auditOpen=ref(false);
const ready=ref(false),password=ref(''),error=ref(''),working=ref(false),tickets=ref<Ticket[]>([]),reviews=ref<Review[]>([]),selected=ref<Ticket|null>(null),messages=ref<Chat[]>([]),draft=ref(''),tab=ref('waiting'),query=ref(''),reviewNote=ref(''),chosenReview=ref<Review|null>(null),thread=ref<HTMLElement|null>(null);
let timer:ReturnType<typeof setInterval>|undefined,refreshing=false,requestVersion=0;
const pendingCount=computed(()=>tickets.value.filter(t=>t.status==='waiting').length);
const reviewCount=computed(()=>reviews.value.filter(t=>t.status==='pending').length);
const filtered=computed(()=>tickets.value.filter(t=>t.status===tab.value && `${t.username} ${t.title} ${t.phone_masked}`.includes(query.value)));
async function call<T=any>(path:string,body?:object):Promise<T>{const r=await fetch('/api/admin'+path,{credentials:'same-origin',method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const data=await r.json();if(!r.ok){if(r.status===401&&path!=='/login'){ready.value=false;tickets.value=[];reviews.value=[];selected.value=null;messages.value=[];requestVersion++;}throw new Error(data.detail||'请求失败');}return data;}
function base(t:Ticket){return `/users/${encodeURIComponent(t.user_id)}/sessions/${encodeURIComponent(t.id)}`;}
function time(value:string){return new Date(value).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});}
function status(value:string){return ({waiting:'等待接入',active:'服务中',closed:'已结束',pending:'待审核',approved:'已通过',rejected:'未通过',executed:'已完成',failed:'失败',cancelled:'已取消'} as Record<string,string>)[value]||value;}
async function loadThread(t:Ticket){const version=++requestVersion;const result=await call(base(t));if(version!==requestVersion||!ready.value)return;const changed=messages.value.at(-1)?.id!==result.messages.at(-1)?.id;selected.value={...t,...result.session};messages.value=result.messages;if(changed){await nextTick();thread.value?.scrollTo({top:thread.value.scrollHeight,behavior:'smooth'});}}
async function refresh(){if(!ready.value||refreshing||auditOpen.value)return;refreshing=true;try{const result=await call('/queue');if(!ready.value)return;tickets.value=result.sessions;reviews.value=result.reviews;if(selected.value){const current=tickets.value.find(t=>t.id===selected.value?.id&&t.user_id===selected.value?.user_id);if(current)await loadThread(current);else {selected.value=null;messages.value=[];requestVersion++;}}}catch(e){error.value=(e as Error).message;}finally{refreshing=false;}}
async function login(){working.value=true;error.value='';try{await call('/login',{password:password.value});password.value='';ready.value=true;await refresh();}catch(e){error.value=(e as Error).message;}finally{working.value=false;}}
async function logout(){try{await call('/logout',{});ready.value=false;tickets.value=[];reviews.value=[];selected.value=null;messages.value=[];requestVersion++;}catch(e){error.value=(e as Error).message;}}
async function select(t:Ticket){error.value='';draft.value='';chosenReview.value=null;selected.value=t;messages.value=[];try{await loadThread(t);}catch(e){error.value=(e as Error).message;}}
async function action(kind:string){if(!selected.value||working.value)return;working.value=true;error.value='';const target=selected.value;try{await call(base(target)+'/'+kind,kind==='messages'?{text:draft.value.trim()}:{});if(kind==='messages')draft.value='';if(kind==='claim')tab.value='active';if(kind==='close')tab.value='closed';await refresh();}catch(e){error.value=(e as Error).message;}finally{working.value=false;}}
async function review(approve:boolean){if(!chosenReview.value||working.value||!reviewNote.value.trim())return;working.value=true;error.value='';try{const item=chosenReview.value;await call(`/users/${encodeURIComponent(item.user_id)}/reviews/${encodeURIComponent(item.id)}`,{approve,note:reviewNote.value.trim()});chosenReview.value=null;reviewNote.value='';await refresh();}catch(e){error.value=(e as Error).message;}finally{working.value=false;}}
onMounted(async()=>{try{await call('/status');ready.value=true;await refresh();}catch{}timer=setInterval(refresh,2000);});
onBeforeUnmount(()=>{clearInterval(timer);requestVersion++;});
</script>

<template>
  <div v-if="!ready" class="login-shell"><section class="login-card"><div class="icon-box"><Headphones :size="28"/></div><span class="eyebrow">YOUSHU · SERVICE DESK</span><h1>人工服务工作台</h1><p>接入用户对话，提供帮助与安全审核。</p><form @submit.prevent="login"><label>管理员密码<input v-model="password" type="password" autocomplete="current-password" required maxlength="128" placeholder="请输入管理员密码"/></label><p v-if="error" class="error" role="alert">{{error}}</p><button class="primary" :disabled="working">{{working?'正在登录…':'进入工作台'}} <ArrowUp :size="16"/></button></form><small><LockKeyhole :size="13"/>独立管理员登录 · 操作记录可追溯</small></section></div>
  <div v-else class="desk"><header><a href="/" class="brand"><span class="brand-icon">有</span><strong>有数 <span>人工服务工作台</span></strong></a><div class="header-right"><button :class="{active:auditOpen}" @click="auditOpen=!auditOpen"><ClipboardList :size="15"/>{{auditOpen?'人工服务':'操作审计'}}</button><span class="online-dot"/>管理员在线<button @click="logout"><LogOut :size="15"/>退出</button></div></header>
    <AdminAudit v-if="auditOpen" :request="call" @close="auditOpen=false;refresh()" @expired="ready=false;auditOpen=false;tickets=[];reviews=[];messages=[];selected=null;requestVersion++"/>
    <aside v-show="!auditOpen"><div class="side-title"><span class="eyebrow">SERVICE INBOX</span><h1>服务收件箱</h1><p>每一次对话，都认真回应。</p></div><div class="tabs"><button :class="{active:tab==='waiting'}" @click="tab='waiting'"><MessageSquare :size="16"/>待接入<b>{{pendingCount}}</b></button><button :class="{active:tab==='active'}" @click="tab='active'"><Headphones :size="16"/>服务中</button><button :class="{active:tab==='closed'}" @click="tab='closed'"><Check :size="16"/>已结束</button><button :class="{active:tab==='reviews'}" @click="tab='reviews';selected=null;messages=[];requestVersion++"><ShieldCheck :size="16"/>解锁审核<b>{{reviewCount}}</b></button></div>
      <label class="search"><Search :size="15"/><input v-model="query" placeholder="搜索用户或对话" aria-label="搜索服务"/></label>
      <div v-if="tab!=='reviews'" class="tickets"><button v-for="t in filtered" :key="t.user_id+t.id" class="ticket" :class="{selected:selected?.id===t.id&&selected?.user_id===t.user_id}" @click="select(t)"><div><strong>{{t.username}}</strong><time>{{time(t.updated_at)}}</time></div><p>{{t.title}}</p><small>{{t.phone_masked}} <span>{{status(t.status)}}</span></small></button><p v-if="!filtered.length" class="empty-small">这里暂时没有对话</p></div>
      <div v-else class="tickets"><button v-for="r in reviews.filter(r=>`${r.username} ${r.phone_masked}`.includes(query))" :key="r.user_id+r.id" class="ticket" @click="chosenReview=r;reviewNote='';selected=null;messages=[];requestVersion++"><div><strong>{{r.username}}</strong><time>{{time(r.created_at)}}</time></div><p>{{r.note}}</p><small>{{r.phone_masked}} <span>{{status(r.status)}}</span></small></button><p v-if="!reviews.length" class="empty-small">暂无解锁申请</p></div>
      <div class="side-footer"><ShieldCheck :size="16"/><span>仅提供客服与审核服务<br/>交易仍由用户本人确认</span></div>
    </aside>
    <main v-show="!auditOpen"><p v-if="error" class="error top-error" role="alert">{{error}}<button @click="error=''">×</button></p>
      <template v-if="chosenReview"><div class="detail-header"><div><span class="eyebrow">ACCOUNT SECURITY</span><h2>人工解锁审核</h2></div><span class="badge">{{status(chosenReview.status)}}</span></div><section class="review-card"><ShieldCheck :size="32"/><h2>{{chosenReview.username}}</h2><p>{{chosenReview.phone_masked}}</p><label>用户申请说明</label><blockquote>{{chosenReview.note}}</blockquote><p class="muted">审核通过后清除本账户的安全锁定；用户需要重新解锁应用，未完成交易不会自动重试。</p><template v-if="chosenReview.status==='pending'"><label>审核说明<textarea v-model="reviewNote" rows="4" maxlength="500" placeholder="填写审核依据及处理说明"/></label><div class="actions"><button :disabled="working||!reviewNote.trim()" @click="review(false)">拒绝申请</button><button class="primary" :disabled="working||!reviewNote.trim()" @click="review(true)">通过并解锁</button></div></template><p v-else>审核说明：{{chosenReview.review_note}}</p><button @click="tab='waiting';chosenReview=null">返回服务对话</button></section></template>
      <template v-else-if="selected"><div class="detail-header"><div><span class="eyebrow">CONVERSATION</span><h2>{{selected.username}} <small>{{selected.phone_masked}}</small></h2><p>{{selected.title}}</p></div><div class="actions"><span class="badge">{{status(selected.status)}}</span><button v-if="selected.status==='waiting'" class="primary" :disabled="working" @click="action('claim')">接入对话</button><button v-if="selected.status==='active'" :disabled="working" @click="action('close')">结束服务</button></div></div><div class="history-note"><ShieldCheck :size="14"/>已同步该对话的历史记录 · 当前为文字服务</div><div ref="thread" class="thread" role="log" aria-label="用户与客服对话"><article v-for="m in messages" :key="m.id" class="message" :class="{operator:m.data.source==='human',user:m.role==='user'}"><div class="message-meta"><strong>{{m.role==='user'?selected.username:m.data.source==='human'?'人工客服':'有数助手'}}</strong><time>{{time(m.created_at)}}</time><span v-if="m.kind!=='text'">{{m.kind==='approval'?'操作确认记录':m.data.handoff_rating?'服务评分':'业务记录'}}</span></div><div class="bubble"><template v-if="m.data.handoff_rating">{{m.data.handoff_rating.half_stars?`用户评分：${m.data.handoff_rating.half_stars/2} / 5`:'等待用户评分'}}</template><template v-else>{{m.text || m.data.title || '业务操作记录'}}</template><p v-if="m.data.status">操作状态：{{m.data.status==='pending'?'待确认':status(m.data.status)}}</p><p v-if="m.data.error">{{m.data.error}}</p><p v-if="m.data.receipt">执行回执：{{m.data.receipt.id || m.data.receipt.operation_id || m.data.receipt.action_id}} {{m.data.receipt.executed_at}}</p><dl v-if="m.data.fields"><div v-for="(f,i) in m.data.fields" :key="i"><dt>{{f.label}}</dt><dd>{{f.value}}</dd></div></dl><div v-if="m.data.result?.display"><p>{{m.data.result.display.title}}</p><dl><div v-for="(metric,j) in m.data.result.display.metrics" :key="j"><dt>{{metric.label}}</dt><dd>{{metric.value}}</dd></div></dl><div class="history-table"><table v-if="m.data.result.display.columns?.length"><thead><tr><th v-for="(column,j) in m.data.result.display.columns" :key="j">{{column}}</th></tr></thead><tbody><tr v-for="(row,j) in m.data.result.display.rows" :key="j"><td v-for="(cell,k) in row" :key="k">{{cell}}</td></tr></tbody></table></div><p>{{m.data.result.display.note}}</p></div></div></article></div><form class="reply-box" @submit.prevent="action('messages')"><textarea v-model="draft" maxlength="4000" rows="3" :disabled="selected.status!=='active'" :placeholder="selected.status==='waiting'?'接入对话后即可回复用户':selected.status==='closed'?'本次服务已结束':'输入回复，发送到用户当前对话…'" aria-label="客服回复"/><div><span>回复仅发送给当前用户的这段对话</span><button class="primary" :disabled="working||selected.status!=='active'||!draft.trim()">发送回复 <ArrowUp :size="16"/></button></div></form></template>
      <div v-else class="welcome"><div class="icon-box"><Headphones :size="34"/></div><span class="eyebrow">READY TO HELP</span><h2>从一段对话开始</h2><p>从左侧选择待接入的对话，<br/>查看历史记录后，为用户提供帮助。</p><div><span>{{pendingCount}}<small>待接入对话</small></span><span>{{reviewCount}}<small>待审核申请</small></span></div></div>
    </main>
  </div>
</template>

<style>
*{box-sizing:border-box}body{margin:0;font-family:Inter,"Microsoft YaHei",sans-serif;color:#263b33;background:#f5f7f3;font-size:14px}button,input,textarea{font:inherit}button{cursor:pointer;display:inline-flex;align-items:center;justify-content:center;gap:8px;border:1px solid #dbe4da;background:white;color:#355447;padding:10px 15px;border-radius:9px}button:hover{background:#f1f5ed}button:disabled{opacity:.45;cursor:default}.primary{background:#285b46;color:white;border-color:#285b46}.primary:hover{background:#1c4d39}input,textarea{color:inherit;background:#fafbf8;border:1px solid #dce4d8;border-radius:9px;padding:12px;outline:none}input:focus,textarea:focus{border-color:#6c977c;box-shadow:0 0 0 3px #285b4610}label{display:grid;gap:10px;font-size:13px}.eyebrow{display:block;font-size:10px;color:#8b998b;font-weight:600;letter-spacing:2px}.icon-box{background:#eaf0e4;color:#426b50;width:66px;height:66px;border-radius:20px;display:grid;place-items:center}.login-shell{min-height:100vh;display:grid;place-items:center;background:radial-gradient(ellipse at 20% 20%,#e6eddd,transparent 60%)}.login-card{width:min(92vw,430px);padding:42px;border:1px solid #e0e7db;border-radius:24px;background:#fff;box-shadow:0 22px 90px #294b3310}.login-card .eyebrow{margin-top:28px}.login-card h1{font-size:26px;letter-spacing:-1px}.login-card p{color:#829080;line-height:1.8;font-size:13px}.login-card form{margin-top:32px}.login-card form button{width:100%;margin-top:22px;justify-content:space-between}.login-card small{margin-top:26px;display:flex;align-items:center;gap:8px;color:#93a08e;font-size:11px}.desk{height:100vh;display:grid;grid-template-columns:306px 1fr;grid-template-rows:76px 1fr}.desk header{grid-column:1/-1;display:flex;align-items:center;justify-content:space-between;padding:0 30px;border-bottom:1px solid #e0e6db;background:#fff}.brand{display:flex;align-items:center;gap:12px;color:inherit;text-decoration:none}.brand-icon{border-radius:10px;background:#315e49;color:#fff;font-weight:bold;padding:10px}.brand strong{font-size:20px}.brand strong span{font-weight:400;font-size:13px;margin-left:16px;padding-left:16px;border-left:1px solid #dfe6da;color:#738574}.header-right{display:flex;align-items:center;gap:8px;font-size:12px;color:#82907e}.header-right button{margin-left:20px;border:0}.online-dot{width:7px;height:7px;border-radius:50%;background:#639c67}.desk aside{position:relative;border-right:1px solid #e0e6db;background:#fbfcf9;display:flex;flex-direction:column;min-height:0;padding-bottom:74px}.side-title{padding:28px 24px 12px}.side-title h1{font-size:22px;letter-spacing:-.5px;margin:12px 0 8px}.side-title p{font-size:12px;color:#8b9787}.tabs{display:grid;grid-template-columns:1fr 1fr;gap:6px;padding:12px 18px}.tabs button{font-size:12px;border:0;background:transparent;justify-content:flex-start;padding:11px 12px}.tabs button.active{background:#e9f0e3;color:#315c42}.tabs b{font-size:10px;border-radius:4px;background:#d8e5cd;padding:2px 5px;margin-left:auto}.search{display:flex;align-items:center;border:1px solid #e3e9df;margin:6px 22px 17px;padding:0 10px;border-radius:9px;color:#99a592;background:#fff}.search input{width:100%;padding:10px 0;border:0;background:transparent;font-size:12px;box-shadow:none}.tickets{overflow:auto;padding:0 12px}.ticket{display:block;text-align:left;width:100%;border:1px solid transparent;background:transparent;padding:16px 12px;margin-bottom:6px}.ticket.selected{border-color:#cddcc6;background:#f0f5ea}.ticket div{display:flex;justify-content:space-between;align-items:center}.ticket strong{font-size:13px}.ticket time{font-size:10px;color:#9aa491}.ticket p{margin:9px 0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-size:12px;color:#72826e}.ticket small{display:flex;justify-content:space-between;font-size:10px;color:#98a38f}.ticket small span{color:#547653}.empty-small{text-align:center;color:#98a58e;font-size:12px;padding:30px 0}.side-footer{position:absolute;bottom:0;left:0;right:0;display:flex;align-items:center;gap:12px;padding:20px 24px;border-top:1px solid #e4eadd;color:#98a38e;font-size:10px;line-height:1.8}.desk main{background:#fff;min-height:0;display:flex;flex-direction:column;position:relative}.detail-header{padding:22px 30px;border-bottom:1px solid #ebeee7;display:flex;align-items:center;justify-content:space-between;gap:12px}.detail-header h2{font-size:18px;margin:10px 0 6px}.detail-header h2 small{font-size:12px;font-weight:400;color:#92a087;margin-left:12px}.detail-header p{font-size:12px;color:#8b9982;margin:0}.actions{display:flex;align-items:center;gap:10px}.badge{font-size:11px;color:#64805d;background:#edf3e7;padding:7px 10px;border-radius:6px;white-space:nowrap}.history-note{padding:13px 30px;display:flex;align-items:center;gap:8px;background:#fafbf7;font-size:11px;color:#93a087}.thread{flex:1;min-height:0;overflow:auto;padding:24px 32px}.message{margin-bottom:24px;max-width:86%}.message.operator{margin-left:auto}.message-meta{display:flex;gap:12px;align-items:center;color:#9aa58f;font-size:10px;margin:0 4px 8px}.message-meta strong{font-size:12px;font-weight:500;color:#728469}.message.operator .message-meta{justify-content:flex-end}.message-meta span{background:#f4f6ef;border-radius:4px;padding:3px 5px}.bubble{background:#f6f8f2;border:1px solid #edf0e7;border-radius:4px 14px 14px 14px;padding:14px 18px;font-size:13px;line-height:1.9;white-space:pre-wrap;overflow-wrap:anywhere}.operator .bubble{background:#eaf2e3;border-color:#dfe9d5;border-radius:14px 4px 14px 14px}.message.user .bubble{background:#fff}.bubble pre{overflow:auto;font-size:10px;white-space:pre-wrap}.bubble dl{font-size:12px}.bubble dl div{display:flex;gap:12px}.bubble dd{margin:0}.bubble dt{color:#91a084}.reply-box{border-top:1px solid #e8ede1;padding:20px 30px}.reply-box textarea{width:100%;resize:vertical;min-height:80px;max-height:180px;background:#fcfdf9}.reply-box>div{display:flex;align-items:center;justify-content:space-between;margin-top:12px}.reply-box span{color:#99a68e;font-size:11px}.welcome{margin:auto;text-align:center;padding:40px;color:#849278}.welcome .icon-box{margin:0 auto 25px;width:80px;height:80px}.welcome h2{font-size:24px;color:#36543d;font-weight:500}.welcome p{font-size:13px;line-height:2}.welcome>div:last-child{display:flex;justify-content:center;gap:50px;border-top:1px solid #e5ebdd;margin-top:30px;padding-top:28px}.welcome>div>span{font-size:26px;color:#58704e}.welcome small{display:block;font-size:11px;color:#9aa78d;margin-top:8px}.error{color:#a64c43!important;font-size:12px;background:#fcf0ed;padding:12px;border-radius:8px}.top-error{margin:12px 24px;display:flex;justify-content:space-between}.top-error button{border:0;padding:0;background:transparent}.review-card{max-width:600px;padding:36px;margin:30px;border:1px solid #e4eadd;border-radius:18px}.review-card>svg{color:#638059}.review-card label{margin-top:25px}.review-card blockquote{margin:12px 0;padding:16px;background:#f5f8f0;line-height:1.8;border-radius:8px;white-space:pre-wrap}.review-card p{font-size:12px;color:#89977c;line-height:1.9}.review-card .actions{margin:20px 0}.review-card textarea{resize:vertical}@media(max-width:800px){.desk{grid-template-columns:230px 1fr}.desk header{padding:0 16px}.brand strong span{display:none}.header-right{font-size:0}.detail-header{padding:18px;flex-wrap:wrap}.thread{padding:18px}.message{max-width:100%}.reply-box{padding:15px}.reply-box span{display:none}.review-card{margin:16px;padding:20px}.side-title{padding-left:20px}}@media(max-width:550px){.desk{grid-template-columns:160px 1fr}.tabs{padding:6px;gap:2px}.tabs button{padding:8px 4px;font-size:11px}.tabs button svg{display:none}.side-title{padding:22px 12px 5px}.side-title h1{font-size:18px}.side-title p,.side-footer,.search{display:none}.tickets{padding:4px}.ticket{padding:12px 6px}.ticket div{display:block}.ticket time{display:block;margin-top:6px}.desk aside{padding-bottom:0}.ticket small{display:block}.ticket small span{margin-left:4px}.detail-header h2 small{display:block;margin:8px 0}.history-note{padding:10px 16px;font-size:10px}.brand strong{font-size:18px}}
</style>

<style>.history-table{overflow:auto;max-width:100%}.history-table table{border-collapse:collapse;white-space:nowrap;font-size:11px}.history-table th,.history-table td{padding:6px 12px;border-bottom:1px solid #e0e7d8;text-align:left}</style>
